-- ABWEHR NOVA: six further distinct models as hidden drafts.
begin;
create temporary table t(slug text primary key,name text,code text,url text,photos text[]) on commit drop;
commit;
select count(*) as моделей,count(*) filter(where is_available) as опубліковано,(select count(*) from public.product_media m where m.product_slug in('abwehr-nova-kadis','abwehr-nova-lissabona','abwehr-nova-triana','abwehr-nova-simpli','abwehr-nova-quadro','abwehr-nova-louna') and m.kind='gallery') as фото_в_галереях,count(*) filter(where image_path is not null) as моделей_з_фото from public.products where slug in('abwehr-nova-kadis','abwehr-nova-lissabona','abwehr-nova-triana','abwehr-nova-simpli','abwehr-nova-quadro','abwehr-nova-louna');
